// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != c.Owner());
        vm.prank(caller);
        bool ok;
        try c.Command(address(0), "") {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
